// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        BankCaller h = new BankCaller();
        bool ok = h.tryAirDrop(c);
        assertTrue(ok, "airDrop from an admissible caller must succeed");
    }
}

contract BankCaller {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function tryAirDrop(ModifierEntrancy c) external returns (bool) {
        try c.airDrop() { return true; } catch { return false; }
    }
}
